class Solution {
public:
    int numSubseq(vector<int>& nums, int target) {
        const int MOD = 1000000007;
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<int> pow2(n + 1, 1);
        for (int i = 1; i <= n; ++i) pow2[i] = 2LL * pow2[i - 1] % MOD;
        int l = 0, r = n - 1, ans = 0;
        while (l <= r) {
            if (nums[l] + nums[r] <= target) {
                ans = (ans + pow2[r - l]) % MOD;
                ++l;
            } else --r;
        }
        return ans;
    }
};
